private System.Numerics.Vector2 ScalePoint(System.Numerics.Vector2 p, int sensor)
	{
		return centers[sensor] + (p - centers[sensor]) * new System.Numerics.Vector2(styles[sensor].Size.x, styles[sensor].Size.y);
	}

